from pipeline.schema import SalesforceSchemaV2, TransformError

logger = logging.getLogger(__name__)

FIELD_RENAME_MAP = {
    "sf_account_id":     "account_id",
    "sf_contact_email":  "contact_email",
    "sf_opportunity_dt": "opportunity_date",
    "sf_arr_usd":        "arr",
    "sf_stage_name":     "stage",
    "sf_owner_id":       "owner_id",
    "sf_created_ts":     "created_at",
    "sf_modified_ts":    "updated_at",
}

REQUIRED_FIELDS = {"account_id", "contact_email", "arr", "stage"}

def rename_fields(record: dict[str, Any]) -> dict[str, Any]:
    return {FIELD_RENAME_MAP.get(k, k): v for k, v in record.items()}

def coerce_types(record: dict[str, Any]) -> dict[str, Any]:
    coerced = dict(record)
    if "arr" in coerced and coerced["arr"] is not None:
        try:
            coerced["arr"] = float(coerced["arr"])
        except (ValueError, TypeError) as e:
            raise TransformError(f"Cannot coerce 'arr' to float: {e}")
    for ts_field in ("created_at", "updated_at", "opportunity_date"):
        if ts_field in coerced and coerced[ts_field] is not None:
            coerced[ts_field] = _parse_iso(coerced[ts_field], ts_field)
    return coerced

def validate_required(record: dict[str, Any]) -> None:
    missing = REQUIRED_FIELDS - {k for k, v in record.items() if v is not None}
    if missing:
        raise TransformError(f"Record missing required fields: {missing}")

def transform_record(raw: dict[str, Any]) -> dict[str, Any]:
    record = rename_fields(raw)
    record = coerce_types(record)
    validate_required(record)
    return record

def transform_batch(batch: list[dict[str, Any]]) -> list[dict[str, Any]]:
